        foreach ($x->fetchAll(PDO::FETCH_NUM) as $r) { $ph = (string)$r[0]; if (isset($first[$ph]) || (string)$r[3] <= $pl[$ph]) continue; $first[$ph] = [(string)$r[1], (string)$r[2], (string)$r[3]]; }
        foreach ($first as $ph => $f) { $n['replied']++; $b = trim(preg_replace('/\s+/u', ' ', $f[0])); if ($b === '' || mb_strlen($b) <= 2 || preg_match($triv, $b) || preg_match('/^[\p{So}\p{Sk}\p{P}\s]+$/u', $b)) { $n['trivial']++; continue; } $n['real']++; if (preg_match('/(price|rate|kitn|kimat|cost|offer|discount|combo|\bml\b|size|chahiye|kya rate|कीमत|कितना|ભાવ|કિંમત)/iu', $b)) $n['asked_price']++;
            $o = $pdo->prepare("SELECT who, ts FROM wa_messages WHERE phone = ? AND dir = 'out' AND ts > ? ORDER BY id LIMIT 1"); $o->execute([$ph, $f[2]]); $a = $o->fetch(PDO::FETCH_NUM);
            if (!$a) { $n['none_now']++; $n['none30']++; $c = (preg_match('/(nahi|nahin|\bno\b|not interested|stop|band kar|mat bhej|unsubscribe|don.?t|bye|नहीं|मत)/iu', $b) ? 'decline' : (preg_match('/(\?|kya|kitn|price|rate|kaise|kab|kahan|how|what|which|available|cod|delivery|order|chahiye|bhej|link|photo|offer|discount|ml|bottle)/iu', $b) ? 'question' : (preg_match('/^\d{6}$/', $b) ? 'pincode' : (mb_strlen($b) <= 12 ? 'short' : 'other')))); $n['c_' . $c] = ($n['c_' . $c] ?? 0) + 1; try { $ct = $pdo->prepare("SELECT status, assigned_emp, cx_id, optout FROM wa_contacts WHERE phone = ? LIMIT 1"); $ct->execute([$ph]); $z = $ct->fetch(PDO::FETCH_NUM); $zk = $z ? ($z[3] ? 'optout' : ($z[2] ? 'complaint' : ((string)$z[0] . ((int)$z[1] > 0 ? '+held' : '+nobody')))) : 'nocontact'; $n['cs_' . $c . '_' . $zk] = ($n['cs_' . $c . '_' . $zk] ?? 0) + 1; if ($z && (string)$z[0] === 'closed' && in_array($c, ['question', 'short'], true)) { $ev = $pdo->prepare("SELECT body FROM wa_messages WHERE phone = ? AND dir = 'sys' AND ts > ? ORDER BY id LIMIT 1"); $ev->execute([$ph, $f[2]]); $eb = (string)$ev->fetchColumn(); $ek = $eb === '' ? '(no event)' : preg_replace('/\d+/', '#', mb_substr(trim(preg_replace('/\s+/u', ' ', $eb)), 0, 48)); $n['cl_' . $c . ' ' . $ek] = ($n['cl_' . $c . ' ' . $ek] ?? 0) + 1; } } catch (Throwable $e) { } continue; } $d = strtotime($a[1]) - strtotime($f[2]); $dly[] = $d; if ($d > 1800) { $n['none30']++; continue; } if ($a[0] === 'bot') $n['bot']++; elseif ($a[0] === 'emp') $n['emp']++; else $n['other']++; } }
    sort($dly); echo "ASK REPLY2 customers who wrote after a Lineup message today " . $n['replied'] . " · trivial (thanks / ok / emoji, no answer needed) " . $n['trivial'] . " · real replies " . $n['real'] . " · answered within 30 min: bot " . $n['bot'] . " person " . $n['emp'] . " other " . $n['other'] . " · NOT answered in 30 min " . $n['none30'] . " (of them nobody answered until now " . $n['none_now'] . ") · never-answered: decline/stop " . ($n['c_decline'] ?? 0) . " question/order words " . ($n['c_question'] ?? 0) . " pincode " . ($n['c_pincode'] ?? 0) . " short " . ($n['c_short'] ?? 0) . " other " . ($n['c_other'] ?? 0) . " · contact state of the never-answered (class_status+holder): " . json_encode(array_filter($n, function ($k) { return strpos($k, 'cs_') === 0; }, ARRAY_FILTER_USE_KEY)) . " · the first system event after the reply (what closed them): " . json_encode(array_filter($n, function ($k) { return strpos($k, 'cl_') === 0; }, ARRAY_FILTER_USE_KEY), JSON_UNESCAPED_UNICODE) . " · asked price/size/offer words " . ($n['asked_price'] ?? 0) . " · median answer delay " . ($dly ? $dly[intdiv(count($dly), 2)] : 'n/a') . "s\n"; } catch (Throwable $e) { echo "ASK REPLY2 ERR " . substr($e->getMessage(), 0, 90) . "\n"; }
// 8) STUDY (owner 22 Nov): of the customers who answered a 30-day Lineup message on a day, how many asked price / size / offer words (could get an aggressive price offer within 1 hour), how many of those ordered anyway within 7 days, and how many had already been given a price. Today and yesterday. Counts only.
try { try { $pdo->exec("SET SESSION MAX_EXECUTION_TIME = 120000"); } catch (Throwable $e) { }
    $ordK = []; foreach ($pdo->query("SELECT phone, created_at FROM shop_orders WHERE created_at >= '" . date('Y-m-d 00:00:00', time() - 2 * 86400) . "' AND phone IS NOT NULL AND phone <> ''")->fetchAll(PDO::FETCH_NUM) as $r) { $kk = substr(preg_replace('/\D+/', '', (string)$r[0]), -10); $ordK[$kk][] = (int)strtotime((string)$r[1]); }
    $pr = '/(price|rate|kitn|kimat|cost|offer|discount|combo|\bml\b|size|chahiye|\d+\s*[x*]\s*\d+|कीमत|कितना|ભાવ|કિંમત)/iu'; $dc = '/(nahi|nahin|\bno\b|not interested|stop|band kar|mat bhej|unsubscribe|don.?t|bye|नहीं|मत)/iu';
    foreach ([0 => 'TODAY', 1 => 'YESTERDAY'] as $back => $lbl) { $d0 = date('Y-m-d 00:00:00', time() - $back * 86400); $d1 = date('Y-m-d 00:00:00', time() - ($back - 1) * 86400); $c = ['repl' => 0, 'auto' => 0, 'optout' => 0, 'decline' => 0, 'trivial' => 0, 'real' => 0, 'asked' => 0, 'asked_ord' => 0, 'asked_priced' => 0, 'asked_noprice' => 0, 'asked_noprice_ord' => 0, 'not_asked' => 0, 'not_asked_ord' => 0];
        $sm = $pdo->prepare("SELECT phone, MAX(sent_at) FROM wa_line_plan WHERE status = 'sent' AND sent_at >= ? AND sent_at < ? GROUP BY phone"); $sm->execute([$d0, $d1]); $pl2 = []; foreach ($sm->fetchAll(PDO::FETCH_NUM) as $r) $pl2[(string)$r[0]] = (string)$r[1];
        foreach (array_chunk(array_keys($pl2), 300) as $ch) { $in = implode(',', array_fill(0, count($ch), '?'));
            $x = $pdo->prepare("SELECT phone, body, ts FROM wa_messages WHERE dir = 'in' AND ts >= ? AND ts < ? AND phone IN ($in) ORDER BY id"); $x->execute(array_merge([$d0, $d1], $ch)); $by = [];
            foreach ($x->fetchAll(PDO::FETCH_NUM) as $r) { $ph = (string)$r[0]; if ((string)$r[2] <= $pl2[$ph]) continue; $by[$ph][] = [(string)$r[1], (string)$r[2]]; }
            if (!$by) continue; $ar = []; $ax = $pdo->prepare("SELECT DISTINCT phone FROM wa_messages WHERE dir = 'sys' AND ts >= ? AND body LIKE 'Auto-reply from another business%' AND phone IN (" . implode(',', array_fill(0, count($by), '?')) . ")"); $ax->execute(array_merge([$d0], array_keys($by))); foreach ($ax->fetchAll(PDO::FETCH_COLUMN) as $ph) $ar[(string)$ph] = 1;
            $oq = $pdo->prepare("SELECT phone, optout, cx_id FROM wa_contacts WHERE phone IN (" . implode(',', array_fill(0, count($by), '?')) . ")"); $oq->execute(array_keys($by)); $ct2 = []; foreach ($oq->fetchAll(PDO::FETCH_NUM) as $r) $ct2[(string)$r[0]] = $r;
            foreach ($by as $ph => $ms) { $c['repl']++; $b = trim(preg_replace('/\s+/u', ' ', $ms[0][0])); if (isset($ar[$ph])) { $c['auto']++; continue; } if (!empty($ct2[$ph][1])) { $c['optout']++; continue; } if (preg_match($dc, $b)) { $c['decline']++; continue; } if ($b === '' || mb_strlen($b) <= 2 || preg_match($triv, $b) || preg_match('/^[\p{So}\p{Sk}\p{P}\s]+$/u', $b)) { $c['trivial']++; continue; }
                $c['real']++; $t1 = strtotime($ms[0][1]); $asked = false; foreach ($ms as $m1) if (strtotime($m1[1]) <= $t1 + 86400 && preg_match($pr, $m1[0])) { $asked = true; break; }
                $kk = substr(preg_replace('/\D+/', '', $ph), -10); $ord = false; foreach ($ordK[$kk] ?? [] as $ot) if ($ot > $t1 && $ot <= $t1 + 7 * 86400) { $ord = true; break; }
                if (!$asked) { $c['not_asked']++; if ($ord) $c['not_asked_ord']++; continue; }
